presetParts.perFrame:
dec_med = exp (-7.5/fps);
dec_slow = exp (-1.6/fps);
dec_xlow = exp (-0.2/fps);

beat = bass+mid+treb; 
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, .2+avg+peak) * above (time, t0+.2);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) %16;
index2 = (index2 + is_beat*bnot(index))%2;

q21 = beat;
q22 = peak;
q23 = index;
q24 = is_beat;
q26 = bass_att + mid_att + treb_att;
q27 = index + 1;


k1 =  is_beat*equal(index%3,0);
p1 =  k1*(p1+1) + (1-k1)*p1;
p2 = dec_med * p2+ (1-dec_med)*p1;
rott = p2 * 3.1416/4;

q1 = cos(rott);
q2 = sin(rott);
q3 = -q2;
q4 = q1;

trel = time/3;
q5 = cos(trel);
q6 = sin(trel);
q7 = -q6;
q8 = q5;

puls = puls*dec_slow + q22*(1-dec_slow);
q17 = min(8,puls+4)*31;
q18 = .006 + .04*(sin(time/14)+1)/2; 
q19 = sin(time*1)*.05;
q20 = cos(time*1.6)*.05;

monitor = q18;

