   rs.y = z*hinten-trel;
   rs = frac(rs.yx)*mask ; 
   neu = GetBlur1(rs) - (1-q18*16)*GetBlur2(rs);
   neu *= normalize(noise1) * 8*saturate(6+hinten)/hinten;
   bfly += abs(neu*blk) * mask * (hinten <= 0);
}

//Wolken
float2 uv4 = uv1;
float z4 = clamp(1/(abs(uv4.y-.1)),-0,18);
rs = float2(uv4.x * z4, z4*2+time)/12 ;
