clouds *= saturate(1-uv.y) ;
clouds *= float3 (.4,.7, 1-uv4.y)*.5;

//Buschwerk
bush = 0;
for (n=0; n<=1; n++) {
  float2 uv5 = uv1+float2 (0,-n*.04);
  uv5.x += (uv.y*1.05* (q19*(n%2) + q20*((n+1)%2)));
  neu = abs(uv5.y)
  *(1+tex2D (sampler_noise_lq,float2(uv5.x*2,uv5.y*2)).g)
  *(3+2*tex2D (sampler_noise_hq,uv5.x/2*(1+n%2)).g);
  neu = saturate(.2*neu-.4) * saturate(-8*uv5.y);
  float red = .5+.5*tex2D (sampler_noise_hq,uv5*2);
  float vis = saturate(4*tex2D (sampler_noise_hq,uv5*8)
  *tex2D (sampler_noise_hq,uv5*24));

  neu *= float3 (2*red,1,.2) *vis ;
  bush = max(bush,neu);

}

float3 scene = saturate(clouds*(1-32*bush)) + bush;

ret = scene*saturate(1-8*bfly)+bfly;
